"""
fix_index_html.py - Replaces templates/index.html with the verified-correct,
tested version, fixing the duplicated script block bug.

Run this from your repo root:
    python fix_index_html.py

This writes the file directly - no copy/paste involved, so there is no
chance of the duplication issue happening again.
"""

import base64
import os

ENCODED_CONTENT = ""

def main():
    target_path = os.path.join("templates", "index.html")

    if not os.path.isdir("templates"):
        print("ERROR: 'templates' folder not found in the current directory.")
        print("Make sure you run this script from your SignSpeakPH repo root")
        print("(the folder containing app.py, templates/, static/, etc.)")
        return

    decoded = base64.b64decode(ENCODED_CONTENT).decode("utf-8")

    if os.path.exists(target_path):
        backup_path = target_path + ".before_fix_backup"
        with open(target_path, "r", encoding="utf-8") as f:
            old_content = f.read()
        with open(backup_path, "w", encoding="utf-8") as f:
            f.write(old_content)
        print(f"Backed up old file to {backup_path} ({len(old_content)} chars)")

    with open(target_path, "w", encoding="utf-8") as f:
        f.write(decoded)

    print(f"Wrote corrected file to {target_path} ({len(decoded)} chars)")

    # Verify the fix
    with open(target_path, encoding="utf-8") as f:
        new_content = f.read()
    count = new_content.count("themeToggleBtn")
    line_count = new_content.count(chr(10)) + 1
    print(f"Verification: 'themeToggleBtn' appears {count} times (expected: 5, since it appears in HTML + 4 JS references)")
    print(f"Verification: file has {line_count} lines (expected: ~494, not 572)")

    if line_count > 550:
        print("WARNING: line count still looks too high - the fix may not have applied correctly.")
    else:
        print("Looks correct - duplication appears to be fixed.")

if __name__ == "__main__":
    main()
